return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Višejezični WordPress, jedna objava po jeziku: povezani prijevodi objava, stranica, kategorija, medijskog teksta, widgeta i naslova web-mjesta, s uvezenim starim Tranzly prijevodima.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI pružatelji usluga','The makers of ChatGPT. A good all-rounder.'=>'Tvorci sustava ChatGPT. Dobar svestrani alat.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvorci modela Claude. Snažan u pisanju i opreznom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Gemini modeli tvrtke Google. Brzo i povoljno.','A European AI company with fast, inexpensive models.'=>'Europska AI tvrtka s brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Jeftini modeli koji su dobri u pisanju i pisanju koda.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih pružatelja usluga.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi poput OpenAI-jeva API-ja, uključujući model koji se izvodi na vašem vlastitom računalu ili poslužitelju.','General (used when nothing more specific is set)'=>'Općenito (koristi se kada nije postavljeno ništa specifičnije)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prijevod','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate dopuštenje za pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ove postavke dijele svi dodaci koji ih koriste: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši su ključevi šifrirani u bazi podataka ove stranice i šalju se samo davatelju usluga kojeg ste odabrali – nikada nama.','Step 1 of 2: choose an AI provider'=>'1. korak od 2: odaberite AI davatelja usluge','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Donosite vlastiti ključ, tako da pružatelju usluga plaćate izravno za ono što koristite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionira; kasnije možete dodati još.','Next'=>'Sljedeće','Step 2 of 2: connect %s'=>'Korak 2 od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu svoje usluge kompatibilne s OpenAI koja završava s /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili izradite besplatan račun).','the %s API keys page'=>'%s stranica API ključeva','Create a new key and copy it.'=>'Izradite novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Zalijepite ga ispod i pritisnite „Spremi i testiraj”. Šaljemo jedan mali zahtjev kako bismo provjerili radi li.','Most providers need a little credit on the account before a key works: %s.'=>'Većina pružatelja usluga treba malo kredita na računu prije nego što ključ počne raditi: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Odaberite drugog pružatelja usluga','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Spremljeni ključ završava s …%s — zalijepite novi da biste ga zamijenili','Key (optional)'=>'Ključ (neobavezno)','API key'=>'API ključ','Save and test'=>'Spremi i testiraj','Providers'=>'Pružatelji usluga','Provider'=>'Pružatelj usluga','Status'=>'Status','Key'=>'Ključ','Get a key'=>'Nabavite ključ','Test'=>'Test','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Spremljeno novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovno unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Spremljeni ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno.','Not connected'=>'Nije spojeno','Connected — last test passed %s'=>'Povezano — posljednji test je prošao %s','Last test failed: %s'=>'Posljednji test nije uspio: %s','Connected — not tested yet'=>'Povezano — još nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Popis uključuje svaki model koji vaš ključ može koristiti, učitan uživo od pružatelja usluge.','— Recommended for the provider —'=>'— Preporučuje se za pružatelja usluga —','Save models'=>'Spremi modele','Refresh the model lists from the providers'=>'Osvježite liste modela od pružatelja usluga','best quality'=>'najbolja kvaliteta','lowest cost'=>'najniža cijena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Danas je izašao novi model? Zalijepite njegov točan naziv kako biste ga odmah počeli koristiti.','Model name'=>'Naziv modela','Add model'=>'Dodaj model','Recommended models list'=>'Popis preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Lista preporučenih modela nije mogla biti potvrđena, stoga se preporuke ne prikazuju. Ponovno instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Korišteni popis objavljen je %s. Svako ažuriranje dodatka donosi novi.','Also check Zinn Digital® once a day for an updated list.'=>'Također provjerite Zinn Digital® jednom dnevno za ažurirani popis.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtjev za preuzimanje: bez ključa, bez adrese web-mjesta, ništa o vašem sadržaju. Popis je potpisan, a popis koji ne prođe provjeru potpisa se zanemaruje.','Last checked %1$s: %2$s.'=>'Zadnja provjera %1$s: %2$s.','Save, and check now if turned on'=>'Spremite i provjerite odmah ako je uključeno','a newer list was installed'=>'instaliran je noviji popis','already up to date'=>'već ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije prošlo provjeru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nije dostupan; trenutačni popis ostaje u upotrebi','turned off'=>'isključeno','Open'=>'Otvori','Check their status page'=>'Provjerite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite svoju stranicu za naplatu','Open your API keys page'=>'Otvorite stranicu s API ključevima','Open the AI settings'=>'Otvorite postavke umjetne inteligencije','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dopuštenje za to.','Unknown provider.'=>'Nepoznati davatelj.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primjer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne izgleda kao API ključ. Kopirajte ga ponovno, bez razmaka.','Paste your API key first.'=>'Prvo zalijepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su spremljeni.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite točan naziv modela, na primjer onako kako je navedeno u dokumentaciji pružatelja usluge.','Added %s. Choose it under "Which model to use".'=>'Dodan %s. Odaberite ga pod "Koji model koristiti".','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se popis koji je došao s dodacima.','Checked: %s.'=>'Odabrano: %s.','Model lists refreshed.'=>'Popisi modela su osvježeni.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ je spremila novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovno unesite ključ u postavkama za AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš spremljeni AI ključ se više ne može otvoriti (sigurnosni ključevi web-mjesta su promijenjeni). Unesite ga ponovno u postavkama umjetne inteligencije.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI još nije podešen. Dodajte ključ za AI davatelja usluga u AI postavkama.','No model is chosen for this task. Pick one in the AI settings.'=>'Ni jedan model nije odabran za ovaj zadatak. Odaberite jedan u postavkama umjetne inteligencije.','That AI provider is not supported by this version of the plugin.'=>'Taj pružatelj usluga umjetne inteligencije nije podržan u ovoj verziji dodatka.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ova stranica ne može dosegnuti vašu AI uslugu. Provjerite radi li i je li njena adresa dostupna s vašeg web poslužitelja (usluga na vašem vlastitom računalu nije dostupna s hostirane stranice).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ova stranica nije mogla dosegnuti %s. Provjerite njihovu stranicu statusa; ako rade, vaš poslužitelj možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš račun nema preostalog kredita ili kvote. Dodajte kredit ili povećajte ograničenje na svom računu kod njih, a zatim pokušajte ponovo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno upisan, opozvan ili je istekao. Izradite novi ključ i zalijepite ga ovdje.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtjev za vaš ključ. Ključ možda nema pristup ovom modelu ili značajci, ili je vaš račun potrebno verificirati.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od davatelja %2$s za vaš ključ. Odaberite drugi model u postavkama umjetne inteligencije.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Vaš plan %2$s ne uključuje model "%1$s". Odaberite drugi model u AI postavkama ili nadogradite svoj plan.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može slati zahtjeve. Pričekajte minutu i pokušajte ponovno ili povećajte ograničenje brzine kod njih.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutačno ima problema (prekid rada ili preopterećenje s njihove strane). S vašim postavkama je sve u redu. Pokušajte ponovno uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Zahtjev za AI nije uspio iz razloga koji nismo mogli utvrditi. Pokušajte ponovno; ako se to nastavi događati, obratite se podršci s detaljima u nastavku.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pružatelj usluga umjetne inteligencije odgovorio je u obliku koji ovaj dodatak nije mogao pročitati. Pokušajte ponovno; ako se to nastavi događati, odaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno s OpenAI)','Save a key for this provider first.'=>'Prvo spremite ključ za ovog pružatelja usluga.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali pružatelj usluge za njega ne navodi nijedan tekstualni model. Dodajte model sami u nastavku.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s je odgovorio/la koristeći %2$s. Vaše AI značajke spremne su za upotrebu.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisnička uloga ne smije koristiti umjetnu inteligenciju na ovoj stranici. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegla svoju mjesečnu potrošnju na umjetnu inteligenciju. Administrator ju može povećati u postavkama umjetne inteligencije.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ova je stranica dosegnula mjesečni limit AI zahtjeva. Administrator ga može povećati u postavkama za AI.','Usage and cost'=>'Upotreba i troškovi','The log, limits and role permissions apply to AI used through: %s.'=>'Dnevnik, ograničenja i dozvole uloga primjenjuju se na AI koji se koristi putem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na temelju objavljenih cijena; model bez poznate cijene računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovaj mjesec: %1$s zahtjeva, oko %2$s.','When'=>'Kada','Who'=>'Tko','Used for'=>'Upotrebljava se za','Model'=>'Model','Tokens in / out'=>'Tokeni / izlazni tokeni','About'=>'O programu','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još nije podnesen nijedan zahtjev za AI.','Done'=>'Gotovo','Limits and permissions'=>'Ograničenja i dozvole','Monthly spending limit (US dollars)'=>'Mjesečni limit potrošnje (US dolara)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. AI se zaustavlja do kraja mjeseca kada približni trošak dosegne tu vrijednost.','Monthly request limit'=>'Mjesečno ograničenje zahtjeva','Leave empty for no limit.'=>'Ostavite prazno za bez ograničenja.','Who may use AI'=>'Tko može koristiti AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa kako biste omogućili svima koji mogu koristiti značajke dodatka da koriste umjetnu inteligenciju. Administratori je uvijek mogu koristiti.','Save limits and permissions'=>'Spremi ograničenja i dozvole','Limits and permissions saved.'=>'Ograničenja i dozvole su spremljeni.','That language is not one of this site\'s languages.'=>'Taj jezik nije jedan od jezika ove stranice.','A translation must be the same kind of content as the original.'=>'Prijevod mora biti iste vrste sadržaja kao i izvornik.','Choose one of the site\'s other languages.'=>'Odaberite jedan od drugih jezika web-mjesta.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripte administratorskog zaslona nedostaju u ovoj kopiji dodatka. Ponovno ga instalirajte iz objavljenog paketa.','This screen needs JavaScript.'=>'Ovaj zaslon zahtijeva JavaScript.','Choose a language'=>'Odaberite jezik','Upgrade'=>'Nadogradite','Pricing'=>'Cijene','Start Trial'=>'Započni probno razdoblje','Account'=>'Korisnički račun','Contact Us'=>'Kontaktirajte nas','Affiliation'=>'Pripadnost','the kind of softwarePlugin'=>'Dodatak','greetingHey %s,'=>'Pozdrav %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Prijavite se kako biste primali obavijesti e-poštom o sigurnosnim i značajnim ažuriranjima, edukativnom sadržaju i povremenim ponudama te kako biste podijelili neke osnovne informacije o WordPress okruženju. To će nam pomoći da učinimo %s kompatibilnijim s vašom web-lokacijom i boljim u obavljanju onoga što vam je potrebno.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Prijavite se za primanje obavijesti e-poštom o sigurnosnim ažuriranjima i značajkama, edukativnom sadržaju i povremenim ponudama te za dijeljenje osnovnih informacija o WordPress okruženju.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ako ovo preskočite, nema problema! %1$s će i dalje raditi ispravno.','Allow & Continue'=>'Dopusti i nastavi','verbSkip'=>'Preskoči','Skipping, please wait'=>'Preskače se, molimo pričekajte','Continue'=>'Nastavi','Please wait'=>'Molimo pričekajte','as activating pluginActivating'=>'Aktiviranje','This will allow %s to'=>'Ovo će omogućiti %s da','Privacy Policy'=>'Pravila o privatnosti','Terms of Service'=>'Uvjeti korištenja','License Agreement'=>'Licencni ugovor','Have a license key?'=>'Imate li licencni ključ?','Activate License'=>'Aktiviraj licencu','View Basic Profile Info'=>'Pregledaj osnovne informacije profila','Your WordPress user\'s: first & last name, and email address'=>'Podaci vašeg WordPress korisnika: ime i prezimen te adresa e-pošte','View Basic Website Info'=>'Pogledajte osnovne informacije o web-mjestu','Homepage URL & title, WP & PHP versions, and site language'=>'URL i naslov početne stranice, verzije WP-a i PHP-a te jezik web-mjesta','View Basic %s Info'=>'Pregledajte osnovne podatke za %s','Current %s & SDK versions, and if active or uninstalled'=>'Trenutne %s & SDK verzije te jesu li aktivne ili deinstalirane','Newsletter'=>'Bilten','Updates, announcements, marketing, no spam'=>'Ažuriranja, obavijesti, marketing, bez neželjene pošte','View Diagnostic Info'=>'Prikaz dijagnostičkih podataka','WordPress & PHP versions, site language & title'=>'WordPress i PHP verzije, jezik i naziv web-mjesta','View Plugins & Themes List'=>'Pregledajte popis dodataka i tema','Names, slugs, versions, and if active or not'=>'Imena, kratki nazivi (slugs), verzije te jesu li aktivni ili ne','optional'=>'neobavezno','Never miss an important update'=>'Nikada ne propustite važnu obavijest','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Uveli smo ovu mogućnost dobrovoljne prijave kako nikada ne biste propustili važno ažuriranje i kako biste nam pomogli da %s učinimo kompatibilnijim s vašom web-lokacijom i boljim u ispunjavanju vaših potreba.','Thank you for updating to %1$s v%2$s!'=>'Hvala vam što ste ažurirali na %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks se mora sastojati od 1 do 8 malih slova ili znamenki, počinjati slovom i ne smije sadržavati naziv dodatka.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" nije jezični kod. Upotrijebite WordPress lokalitet kao što je fr_FR ili de_DE.','List at least one language.'=>'Navedite barem jedan jezik.','You are not allowed to translate this item.'=>'Nije vam dopušteno prevesti ovu stavku.','This item already has a version in that language.'=>'Ovaj predmet već ima verziju na tom jeziku.','That translation engine is not available on this site.'=>'Taj mehanizam za prevođenje nije dostupan na ovoj web-lokaciji.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Različiti mehanizmi po jeziku, automatska alternativa i ograničenja potrošnje značajke su su Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Svaki jezik mora biti jedan od jezika stranice, s dostupnim pogonom.','The fallback list may only name available engines.'=>'Rezervni popis može sadržavati samo dostupne mehanizme.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Mjesečni limit je iznos u US dolarima, nula ili više, za dostupni mehanizam.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Preferirani prijevodi i ton po jeziku značajke su su paketa Tranzly Pro. Popis pojmova koji se ne prevode besplatan je.','Glossary entries must be grouped by one of the site\'s languages.'=>'Unosi u rječnik moraju biti grupirani prema jednom od jezika web-mjesta.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Ton se postavlja po jeziku web-mjesta: zadana razina formalnosti, više ili manje, uz opcionalne upute.','The value for %s is not one of the allowed choices.'=>'Vrijednost za %s nije među dopuštenim opcijama.','The background queue is not available on this site.'=>'Pozadinski red čekanja nije dostupan na ovoj stranici.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Zadatak prevođenja izvodi se kao osoba koja ga pokreće, stoga korisnik mora biti prijavljen.','There is nothing you are allowed to translate in that selection.'=>'U tom odabiru nema ničega što vam je dopušteno prevesti.','That item is not part of a translation job.'=>'Ta stavka nije dio posla prevođenja.','You are not allowed to change that translation.'=>'Nije vam dopušteno promijeniti taj prijevod.','This item\'s group already has a %1$s version (#%2$d).'=>'Grupa ovog stavka već ima %1$s verziju (#%2$d).','An item cannot be its own translation.'=>'Stavka ne može biti vlastiti prijevod.','That item is already a translation of something else. Unlink it first.'=>'Ta je stavka već prijevod nečega drugog. Najprije je odspojite.','The translation link could not be saved.'=>'Veza za prijevod nije mogla biti spremljena.','That text cannot be translated here.'=>'Taj se tekst ovdje ne može prevesti.','That media text cannot be translated here.'=>'Ovaj medijski tekst se ovdje ne može prevesti.','A translation can be published or kept as a draft.'=>'Prijevod se može objaviti ili spremiti kao nacrt.','You are not allowed to publish this kind of content.'=>'Nije vam dopušteno objavljivanje ove vrste sadržaja.','This item is already written in that language.'=>'Ova stavka je već napisana na tom jeziku.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Ovaj prijevod je uredila osoba (ili je uvezen), pa je zaštićen. Otključajte ga kako biste ga ponovno preveli.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Još uvijek nije postavljen ni jedan prevoditeljski mehanizm. Dodajte ključ za jedan u Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Taj stroj za prevođenje još nije podešen: prvo dodajte njegov ključ.','The same text is being translated by another job right now; this item will use that answer.'=>'Isti tekst se trenutno prevodi u drugom zadatku; ova stavka će koristiti taj prijevod.','No translation engine could take this item.'=>'Nijedan stroj za prevođenje nije mogao prihvatiti ovu stavku.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Mehanizam nije vratio prijevod za svaki dio ove stavke. Ništa nije promijenjeno.','AI model'=>'AI model','AI model (%1$s %2$s)'=>'AI model (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s trenutačno ima poteškoća. Pokušajte ponovno uskoro ili upotrijebite drugi mehanizam.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Vaša stranica nije mogla dosegnuti %s. Provjerite može li uspostavljati odlazne veze, a zatim pokušajte ponovno.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s nije prihvatio vaš ključ API. Provjerite ključ u odjeljku Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Vaš %s račun je potrošio svoju kvotu ili saldo. Nadopunite ga kod njih ili upotrijebite drugi mehanizam.','%s asked us to slow down. It will be tried again automatically.'=>'%s je zatražio da usporimo. Ponovni pokušaj bit će izvršen automatski.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Ovaj je tekst predug za %s u jednom prolazu. Podijelite sadržaj ili upotrijebite drugi mehanizam.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s je odbio prevesti ovaj sadržaj. Pokušajte s drugim prevoditeljem ili ga prevedite ručno.','%s does not translate this language. Choose another engine for it.'=>'%s ne prevodi ovaj jezik. Odaberite drugi mehanizam za njega.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Dosegnut je ovogodišnji limit potrošnje za %s, tako da mu ništa više nije poslano. Povećajte limit u Tranzly → Engines ili pričekajte sljedeći mjesec.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Prevođenje s %s nije uspjelo iz razloga koji Tranzly nije mogao identificirati. Detalji su u nastavku.','An engine id must be lowercase letters, digits and hyphens.'=>'ID mehanizma mora sadržavati samo mala slova, znamenke i crtice.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Izradio Neil Lock, izvršni direktor tvrtke Zinn Digital® Ltd','Version %s'=>'Verzija %s','Tranzly website'=>'Tranzly web-stranica','Zinn Digital® website'=>'Web-mjesto za Zinn Digital®','Settings saved.'=>'Postavke su spremljene.','See the Pro plans and pricing'=>'Pogledajte Pro planove i cijene','Languages'=>'Jezici','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Prvi jezik je onaj na kojem je vaš sadržaj napisan. Posjetitelji se prebacuju pomoću bloka za prebacivanje jezika.','(default)'=>'(zadano)','Locale code'=>'Jezični kod','For example fr_FR'=>'Na primjer fr_FR','Name (optional)'=>'Naziv (nije obavezno)','For example Français'=>'Na primjer Français','Add language'=>'Dodaj jezik','Front-end output'=>'Izlaz sučelja','Class name prefix'=>'Prefiks naziva klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Svaki naziv klase koji dodatak ispisuje na vašim stranicama počinje s ovim prefiksom, tako da stranice ne otkrivaju koji ih je dodatak izradio. 1 do 8 malih slova ili znamenaka, s početnim slovom.','Beta updates'=>'Beta ažuriranja','This site receives beta versions as updates.'=>'Ova stranica prima beta verzije kao ažuriranja.','This site receives stable versions only.'=>'Ova stranica prima samo stabilne verzije.','Change this on the Account page'=>'Promijenite ovo na stranici Račun','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta verzije nude se licenciranim Pro instalacijama koje su povezane s njihovim računom. Nakon što se povežete, možete se pridružiti sa stranice Račun.','Save settings'=>'Spremi postavke','First engine that is set up'=>'Prvi uslužni program koji je postavljen','Key saved. It is stored encrypted and never shown again.'=>'Ključ je spremljen. Pohranjen je šifrirano i više se nikada neće prikazati.','Engine settings saved.'=>'Postavke stroja su spremljene.','Glossary saved.'=>'Pojmovnik je spremljen.','Your keys'=>'Vaši ključevi','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly poziva usluge prevođenja s vašim vlastitim računom. Ključevi se pohranjuju šifrirano u vašoj bazi podataka i šalju se isključivo onoj usluzi kojoj pripadaju. Ključevi AI modela postavljaju se u postavkama umjetne inteligencije.','%s API key'=>'%s API ključ','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Spremljeno: %s. Unesite novi ključ da biste ga zamijenili ili spremite prazno polje da biste ga uklonili.','No key saved.'=>'Nema spremljenog ključa.','Azure region (leave empty for a global resource)'=>'Azure regija (ostavite prazno za globalni resurs)','Save key'=>'Spremi ključ','Check my DeepL usage'=>'Provjeri moju upotrebu DeepL','%1$s of %2$s characters used this billing period.'=>'Iskorišteno je %1$s od %2$s znakova u ovom obračunskom razdoblju.','Which engine translates'=>'Koji pokretač prevodi','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Još nije postavljen nijedan mehanizam. Spremite ključ iznad (ili postavite AI model) kako biste započeli prevođenje.','Default engine'=>'Zadani mehanizam','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Zaseban mehanizam po jeziku, automatska rezervna opcija i mjesečna ograničenja potrošnje značajke su su paketa Tranzly Pro.','Engine for %s'=>'Pogon za %s','The default engine'=>'Zadani pogon','If an engine fails or reaches a limit, try these next, in this order'=>'Ako motor otkaže ili dosegne ograničenje, pokušajte sljedeće, ovim redoslijedom','Monthly spending caps'=>'Mjesečni limit potrošnje','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Kada mehanizam dostigne svoje ograničenje, ništa mu se više ne šalje do sljedećeg mjeseca, a izvješće o neuspjelom prevođenju navodi razlog. Ostavite prazno za bez ograničenja.','%1$s (spent this month: $%2$s)'=>'%1$s (potrošeno ovog mjeseca: $%2$s)','Save caps'=>'Spremi velika slova','Glossary and words never translated'=>'Rječnik i riječi koje se nikada ne prevode','Never translate these words (one per line)'=>'Nikada nemoj prevoditi ove riječi','Brand and product names stay exactly as they are, with every engine.'=>'Imena brendova i proizvoda ostaju točno kakva jesu, kod svakog mehanizma.','Preferred translations and tone per language are Tranzly Pro features.'=>'Željeni prijevodi i ton po jeziku značajke su su Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Preferirani prijevodi (jedan po retku: termin = prijevod)','Formality'=>'Formalnost','Default'=>'Zadano','Formal'=>'Formalan','Informal'=>'Neformalno','Style instructions (audience, brand voice)'=>'Upute za stil (publika, glas brenda)','Save glossary'=>'Spremi rječnik','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Posao je započet s %d prijevoda za obradu. Izvršava se u pozadini: možete zatvoriti ovu stranicu.','Queued again.'=>'Ponovno u redu čekanja.','Running'=>'Pokretanje','Finished'=>'Završeno','Cancelled'=>'Otkazano','Translate in the background'=>'Prevedi u pozadini','Set up a translation engine in the Engines tab first.'=>'Najprije postavite mašinu za prevođenje na kartici Mašine.','Translate every'=>'Prevedi sve','Into'=>'U','With'=>'Sa','Each language’s own engine'=>'Vlastiti mehanizam svakog jezika','Publish the translations (otherwise they are saved as drafts)'=>'Objavite prijevode (inače se spremaju kao skice)','Estimate the cost'=>'Izračunaj trošak','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d objava, %2$s znakova. Cijena za ovaj mehanizam nije poznata unaprijed.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d objavljenih članaka, %2$s znakova: otprilike $%3$s na vašem vlastitom računu.','Start translating'=>'Započni prevođenje','Jobs'=>'Zadaci','No translation jobs yet.'=>'Još nema poslova prevođenja.','Job %1$d — %2$s'=>'Posao %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d od %2$d prevedeno, %3$d nije uspjelo, %4$d preskočeno (zaštićeno ili već na tom jeziku)','Stop this job'=>'Zaustavi ovaj zadatak','See what failed and why'=>'Pogledajte što nije uspjelo i zašto','Content'=>'Sadržaj','Language'=>'Jezik','What went wrong'=>'Što je pošlo po zlu','Fix it'=>'Popravi to','Details'=>'Pojedinosti','Retry with'=>'Ponovno pokušaj s','The same engine'=>'Isti pogon','Retry'=>'Pokušaj ponovno','Translate by hand'=>'Prevedi ručno','Languages and settings'=>'Jezici i postavke','Engines'=>'Mehanizmi','Translation jobs'=>'Poslovi prevođenja','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Dodajte drugi jezik pod opcijom Tranzly u administrativnom izborniku i preklopnik će se pojaviti ovdje.','Switcher'=>'Preklopnik','Accessible label'=>'Pristupačna oznaka','block titleLanguage switcher'=>'Jezični preklopnik','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Poveznice na ovu stranicu na svim jezicima web-mjesta. Ne prikazuje se ništa dok nisu navedena dva ili više jezika.','block keywordlanguage'=>'Jezik','block keywordswitcher'=>'prebacivač','block keywordtranslation'=>'prijevod']];